--- Writes its arguments to the chat log (dim) and vana-client.log.
---@param ... any values, tab-separated
function print(...) end

--- Loads a Lua file from the mod's folder once (a.b is a/b.lua or a/b/init.lua) and returns what it returned.
---@param name string module name
---@return any
function require(name) end

--- Pauses the running handler for `seconds` (other handlers and the game go on).
---@param seconds? number default 0: the next frame
function sleep(seconds) end

--- Pauses the running handler for `n` frames.
---@param n? integer default 1
function sleep_frames(n) end

--- Pauses the running handler until `test()` returns true (checked once a frame), or `timeout` seconds pass.
---@param test fun(): boolean the condition
---@param timeout? number seconds; none waits for ever
function wait_until(test, timeout) end

--- Seconds since the mod was loaded (monotonic).
---@return number
function clock() end

--- Writes a line to vana-client.log.
---@param text string 
function log.info(text) end

--- Writes a warning to vana-client.log.
---@param text string 
function log.warn(text) end

--- Writes an error to vana-client.log.
---@param text string 
function log.error(text) end

--- Writes a debug line to vana-client.log (shown with debug logging on).
---@param text string 
function log.debug(text) end

--- Calls `handler` on every `event` (see the events list), as a coroutine that may sleep. Higher priority runs first.
---@param event vana.Event|string event name
---@param handler function its arguments are the event's
---@param options? {priority: integer?} 
---@return integer
function events.on(event, handler, options) end

--- Removes a handler added by events.on.
---@param id integer what events.on returned
function events.off(id) end

--- Adds a command: typed as //name or /name, it calls `handler` with the words after it.
---@param name string without the slash
---@param handler fun(...: string) 
function commands.register(name, handler) end

--- Runs a line as if the player had typed it (game commands, our commands, other mods' commands). Any line but a //mod command is a game action: it needs actions (while handling the player's input) or automation.
---@param line string e.g. '/ma "Cure" <t>'
function commands.run(line) end

--- Runs `filter` on every chat line before it is kept: return nil to keep it, false to drop it, or new text (and optionally a new mode) to replace it. Runs inline: it cannot sleep or read game state.
---@param filter fun(text: string, mode: integer?, battle: boolean): (string|false|nil, integer?) 
---@return integer
function filters.chat(filter) end

--- Runs `filter` on every line typed or run (macros, mods) before the command parser: nil keeps it, false drops it, a string replaces it. Runs inline.
---@param filter fun(line: string): string|false|nil 
---@return integer
function filters.typed(filter) end

--- Removes a filter.
---@param id integer what filters.chat / filters.typed returned
function filters.off(id) end

--- Creates or replaces a window: title, width, help, and elements in order. Element types: text {id, text, dim}; buttons {id, label, items, marked} (marked makes them options); slider {id, label, steps, at, shown}; list {id, rows, at, height}; gauge {id, label, value 0..1, text, kind hp|mp|tp|cast|experience|recast}; separator. Indexes are 1-based. Window options: hud (never takes the keys), frame = false (no frame), x / y (its place in the classic UI). It draws in the active UI's look (classic Config page or modern panel).
---@param id string 
---@param spec vana.WindowSpec 
function ui.window(id, spec) end

--- Changes one element of a window (only the fields given): e.g. a list's rows, a text's text, a slider's at and shown.
---@param id string window
---@param element string element id
---@param fields table 
function ui.update(id, element, fields) end

--- Shows a window and gives it the keys (arrows, Enter, Escape); the mouse works in both UIs.
---@param id string 
function ui.open(id) end

--- Shows a window without giving it the keys (a HUD: hud = true windows never take them; a click still acts).
---@param id string 
function ui.show(id) end

--- Hides a window.
---@param id string 
function ui.close(id) end

--- Whether a window shows.
---@param id string 
---@return boolean
function ui.is_open(id) end

--- The window's handler: called with the window id and an event {kind = 'press' | 'set' | 'select' | 'close', id = element id, index = 1-based}.
---@param id string 
---@param handler fun(window: string, event: {kind: string, id: string?, index: integer?}) 
function ui.on(id, handler) end

--- Hooks received packets (one id, or every one when nil) before the client reads them. The handler gets {id, data, original, injected, blocked, outgoing} (data and original are the whole sub-packet, header included) and returns nil to leave it, false to block it, or new bytes. Hooks chain across mods: a blocked packet still reaches later ones. Needs packets.read; changing or blocking needs packets.write.
---@param id integer? packet id
---@param handler fun(p: vana.Packet): (string|false|nil) 
---@return integer
function packets.on_in(id, handler) end

--- Hooks packets about to be sent, after the client built them; as on_in.
---@param id integer? packet id
---@param handler fun(p: vana.Packet): (string|false|nil) 
---@return integer
function packets.on_out(id, handler) end

--- Removes a packet hook.
---@param id integer what on_in / on_out returned
function packets.off(id) end

--- Hands the client a packet as if the server had sent it (it passes the hooks, injected = true). Needs packets.write.
---@param id_or_data integer|string an id, or a whole sub-packet
---@param body? string the body after the 4-byte header
function packets.inject_in(id_or_data, body) end

--- Sends a packet to the server (it passes the hooks, injected = true). Needs packets.write.
---@param id_or_data integer|string an id, or a whole sub-packet
---@param body? string the body after the 4-byte header
function packets.inject_out(id_or_data, body) end

--- A whole sub-packet from an id and its body (the header's size made to fit; at most 508 bytes in all).
---@param id integer 
---@param body string 
---@return string
function packets.build(id, body) end

--- The last packet of an id seen each way, or nil. Needs packets.read.
---@param direction 'in'|'out' 
---@param id integer 
---@return string?
function packets.last(direction, id) end

--- Adds a line to the chat log. With a mode it takes that mode's colour, filters and indent, like a game line; {colour = mode} takes only the mode's colour.
---@param text string 
---@param how? integer|{mode: integer?, colour: integer?} the game's chat mode (0..255), or a table
function chat.add(text, how) end

--- The chat line: whether it is open, and its text.
---@return {open: boolean, text: string}
function chat.line() end

--- Opens the chat line with `text` (the player still presses Enter), or closes it with open = false.
---@param text? string 
---@param open? boolean default true
function chat.set_line(text, open) end

--- Sees every key press, repeat and release before the game and the UI do: {key, down, repeated, ctrl, alt, shift, typing, blocked}. Return true to take it from the game (needs input.capture; its repeats and release go with it). Filters chain across mods: a taken key still reaches later ones with blocked = true. It is the player's input: actions may act here.
---@param handler fun(e: vana.KeyEvent): boolean? 
---@return integer
function input.on_key(handler) end

--- Sees the mouse before the game and the UI do: {kind = 'down' | 'up' | 'move' | 'wheel', button (left, right, middle, back, forward), x, y (window pixels), delta (wheel notches, up positive), blocked}. Return true to take it (needs input.capture).
---@param handler fun(e: vana.MouseEvent): boolean? 
---@return integer
function input.on_mouse(handler) end

--- Removes a key or mouse filter.
---@param id integer what on_key / on_mouse returned
function input.off(id) end

--- Whether a key is held (a name as on_key gives it, or shift / ctrl / alt / win for either side).
---@param key string 
---@return boolean
function input.held(key) end

--- The modifier keys held.
---@return {ctrl: boolean, alt: boolean, shift: boolean, win: boolean}
function input.modifiers() end

--- The pointer (window pixels) and its buttons.
---@return {x: number, y: number, left: boolean, right: boolean, middle: boolean}
function input.mouse() end

--- Whether a text field (the chat line, a search, the map's...) has the keys.
---@return boolean
function input.typing() end

--- Presses and releases a key, with modifiers ("enter", "ctrl+f1", "^1"), as the keyboard would this frame. Needs input.capture.
---@param key string 
function input.press(key) end

--- Holds a key down or lets it go. Needs input.capture.
---@param key string 
---@param down boolean 
function input.send(key, down) end

--- Binds a key with exact modifiers ("f9", "ctrl+1", Windower's "^!f1": ^ Ctrl, ! Alt, ~ Shift, @ Win) to a line run as typed or a function. The key is taken from the game. A line other than a //mod command is a game action (needs actions). Options: up (fire on release), typing (fire while a text field is open too).
---@param key string 
---@param action string|function 
---@param options? {up: boolean?, typing: boolean?} 
function binds.set(key, action, options) end

--- Removes the mod's binds of a key.
---@param key string 
function binds.unset(key) end

--- The mod's binds.
---@return {key: string, line: string?, up: boolean, typing: boolean}[]
function binds.list() end

--- Calls `handler` once after `seconds`.
---@param seconds number 
---@param handler function 
---@return integer
function timer.after(seconds, handler) end

--- Calls `handler` every `seconds` until cancelled.
---@param seconds number at least 0.01
---@param handler function 
---@return integer
function timer.every(seconds, handler) end

--- Stops a timer.
---@param id integer what timer.after / timer.every returned
function timer.cancel(id) end

--- Our character: name, id, index, zone, pos {x, y, z}, heading, status, hp / mp / tp and their percents, maxima, jobs and levels, target id.
---@return vana.Player
function game.player() end

--- The zone id, or nil while zoning.
---@return integer?
function game.zone() end

--- An entity in range by server id or index, or nil.
